CREATE OR REPLACE FUNCTION private.dispatch_tick(p_batch integer DEFAULT 25, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  claimed uuid[]; r record; candidate record; res jsonb; profile_requeue jsonb;
  tick_started timestamptz := clock_timestamp(); tick_budget numeric := 40; deferred integer := 0;
  processed integer := 0; sent integer := 0; stopped integer := 0; failed integer := 0;
  reason text; next_at timestamptz;
begin
  if p_batch is null or p_batch < 1 or p_batch > 200 then p_batch := 25; end if;

  -- MATCH-V1 (owner 2026-10-07): a direct profile write (the manual profile editor) brings the open tasks back
  -- to the queue as the RPC saves do: once per change, before this tick claims anything. A failure here is
  -- reported in the result and never stops the dispatch.
  begin
    profile_requeue := private.requeue_changed_worker_profiles_v1(p_at);
  exception when others then
    profile_requeue := jsonb_build_object('status','ERROR','reason',left(sqlerrm,200));
  end;

  -- MATCH-V1: the time budget of this tick (private.marketplace_config 'match_v1_dispatch', tickBudgetSeconds, default 40 s). One wave
  -- to hundreds of workers takes seconds. After the budget this tick starts no further task: the claimed tasks it did not start are
  -- released and come first on the next tick, so one heavy minute can never run into the statement timeout, roll back and repeat
  -- forever. At least one task is always handled. A bad setting never stops the dispatch (default 40 s).
  begin
    select coalesce((value->>'tickBudgetSeconds')::numeric, 40) into tick_budget
      from private.marketplace_config where key = 'match_v1_dispatch';
  exception when others then
    tick_budget := 40;
  end;
  tick_budget := least(greatest(coalesce(tick_budget, 40), 0.001), 100);

  -- Claim each free Need and queue in a bounded successful-claim batch.
  -- locked_until je zastita od procesa koji padne usred obrade.
  -- Each attempt locks its Need before its queue. A skipped queue rolls back
  -- this small subtransaction, releasing that unsuccessful Need lock. Thus a
  -- queue-only holder cannot starve the next free item or accumulate held Needs.
  claimed := '{}'::uuid[];
  for candidate in
    select s.need_id from private.dispatch_schedule s
    where s.next_run_at <= p_at
      and (s.locked_until is null or s.locked_until < p_at)
    order by s.next_run_at, s.need_id
  loop
    begin
      perform 1 from public.needs n where n.id = candidate.need_id
        for update of n skip locked;
      if not found then continue; end if;
      perform 1 from private.dispatch_schedule s
        where s.need_id = candidate.need_id and s.next_run_at <= p_at
          and (s.locked_until is null or s.locked_until < p_at)
        for update of s skip locked;
      if not found then
        raise exception using errcode = 'UD108', message = 'DISPATCH_QUEUE_SKIPPED';
      end if;
      update private.dispatch_schedule s
        set locked_until = p_at + interval '2 minutes', updated_at = statement_timestamp()
        where s.need_id = candidate.need_id;
      claimed := array_append(claimed, candidate.need_id);
    exception when sqlstate 'UD108' then
      null;
    end;
    exit when cardinality(claimed) >= p_batch;
  end loop;

  for r in select unnest(claimed) as need_id loop
    if processed > 0 and clock_timestamp() - tick_started > make_interval(secs => tick_budget) then
      update private.dispatch_schedule set locked_until = null where need_id = r.need_id;
      deferred := deferred + 1;
      continue;
    end if;
    processed := processed + 1;
    begin
      res := private.dispatch_next_wave(r.need_id);
      reason := coalesce(res->>'reason', res->>'status');

      if (res->>'status') = 'SENT' then
        sent := sent + 1;
        -- Sledeci talas tek kad se prozor ovog zatvori.
        next_at := coalesce((res->>'deadlineAt')::timestamptz, p_at + interval '15 minutes');
        update private.dispatch_schedule
           set next_run_at = next_at, locked_until = null, attempts = 0,
               last_status = 'SENT', last_reason = null, updated_at = statement_timestamp()
         where need_id = r.need_id;

      elsif reason in ('SLOTS_FILLED','NEED_NOT_OPEN','WAVES_EXHAUSTED',
                       'RESPONSE_TARGET_AND_COVERAGE_REACHED','REMAINING_SEARCH_CLOSED',
                       'SEARCH_WINDOW_CLOSED') then
        stopped := stopped + 1;
        delete from private.dispatch_schedule where need_id = r.need_id;

      else
        -- NO_ELIGIBLE_CANDIDATES i slicno: eksponencijalno odlaganje do sest sati, bez odustajanja
        -- (PKG-027a). Promena kod radnika vraca zadatak u red odmah (requeue_open_needs_for_worker_v5).
        stopped := stopped + 1;
        update private.dispatch_schedule
           set attempts = attempts + 1,
               locked_until = null,
               next_run_at = p_at + make_interval(
                 mins => least(360, greatest(5, (2 ^ least(attempts, 9))::integer))),
               last_status = 'STOPPED', last_reason = reason,
               updated_at = statement_timestamp()
         where need_id = r.need_id;
      end if;

    exception when others then
      failed := failed + 1;
      update private.dispatch_schedule
         set attempts = attempts + 1, locked_until = null,
             next_run_at = p_at + interval '10 minutes',
             last_status = 'ERROR', last_reason = left(sqlerrm, 200),
             updated_at = statement_timestamp()
       where need_id = r.need_id;
    end;
  end loop;

  return jsonb_build_object('processed',processed,'sent',sent,'stopped',stopped,
                            'failed',failed,'batch',p_batch,'claimed',cardinality(claimed),
                            'deferred',deferred,'profileRequeue',profile_requeue);
end;
$function$

CREATE OR REPLACE FUNCTION private.marketplace_tick(p_batch integer DEFAULT 25, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare expiry jsonb;dispatch jsonb;completion jsonb;export_maintenance jsonb;retention_maintenance jsonb;ai_turn_sweep jsonb;
begin
 expiry:=private.expire_lifecycle(p_at);dispatch:=private.dispatch_tick(p_batch,p_at);
 completion:=to_jsonb(public.rpc_tick_auto_completion());export_maintenance:=private.data_export_maintenance(p_batch);
 retention_maintenance:=private.retention_maintenance(p_batch);
 ai_turn_sweep:=private.ai_turn_sweep_v5(p_at);
 return jsonb_build_object('at',p_at,'expiry',expiry,'dispatch',dispatch,'completion',completion,'authoritative',true,
 'exportMaintenance',export_maintenance,'retentionMaintenance',retention_maintenance,'aiTurnSweep',ai_turn_sweep);
end $function$
